"""Evaluate layered configuration requests against a policy."""

import re

_SIGNED_DECIMAL = re.compile(r"[+-]?[0-9]+\Z")


def _failure(code):
    return {"ok": False, "config": {}, "error": code}


def _environment_value(value, expected_type):
    if not isinstance(value, str):
        return False, None
    if expected_type == "boolean":
        if value == "true":
            return True, True
        if value == "false":
            return True, False
        return False, None
    if expected_type == "integer":
        if not _SIGNED_DECIMAL.fullmatch(value):
            return False, None
        return True, int(value, 10)
    if expected_type == "string":
        return True, value
    return False, None


def _has_exact_type(value, expected_type):
    if expected_type == "boolean":
        return type(value) is bool
    if expected_type == "integer":
        return type(value) is int
    if expected_type == "string":
        return type(value) is str
    return False


def evaluate(request, policy):
    """Apply request layers and environment overrides in order."""
    defaults = policy.get("defaults", {})
    types = policy.get("types", {})
    known_keys = set(defaults) | set(types)
    config = dict(defaults)

    for layer in request.get("layers", []):
        for key, value in layer.items():
            if key not in known_keys:
                return _failure("unknown_key")
            if value is None and policy.get("null_resets") is True:
                if key in defaults:
                    config[key] = defaults[key]
                else:
                    config.pop(key, None)
            else:
                config[key] = value

    environment = request.get("environment")
    if environment is None and "env" in request:
        environment = request["env"]
    if environment is not None:
        if policy.get("environment") is not True:
            return _failure("environment")
        for key, raw_value in environment.items():
            if key not in known_keys:
                return _failure("unknown_key")
            valid, parsed = _environment_value(raw_value, types.get(key))
            if not valid:
                return _failure("environment")
            config[key] = parsed

    for key, expected_type in types.items():
        if key not in config or not _has_exact_type(config[key], expected_type):
            return _failure("type")

    return {"ok": True, "config": config, "error": None}

